// Monta o cartao do Discord. LGPD: so dados de rede (OLT, PON, CTO, portas, contagens). Nenhum ID de cliente.
const CANAL = '<id-do-canal>';
const API = 'https://discord.com/api/v10';
const COR = { novo: 0xD32F2F, agravado: 0xF57C00, normalizado: 0x2F6E1A };
const ICONE = { novo: '🔴', agravado: '🟠', normalizado: '🟢' };
const corta = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

return $input.all().filter(i => i.json.id).map(({ json: a }) => {
  const ctos = a.ctos || [];
  const teste = String(a.chave).startsWith('teste') ? '[TESTE] ' : '';
  const pct = a.total ? Math.round((a.afetados / a.total) * 100) : 0;
  const nomeCto = ctos[0] ? (ctos[0].descricao || `CTO ${ctos[0].cto}`) : `CTO ${a.chave}`;
  const titulo = a.nivel === 'PON'
    ? `${ICONE[a.evento]} ${teste}PON sem sinal — ${a.olt || 'OLT ?'} · PON ${a.ponid || '?'}`
    : `${ICONE[a.evento]} ${teste}CTO fora — ${nomeCto}`;

  let desc;
  if (a.evento === 'normalizado') {
    desc = `**Normalizado** às ${a.fim} · duração **${a.duracao}**\nEra: ${a.afetados} de ${a.total} clientes offline (${pct}%) desde ${a.inicio}`;
  } else {
    desc = `**${a.afetados} de ${a.total}** clientes offline (**${pct}%**) desde **${a.inicio}**`
         + (a.evento === 'agravado' ? '\n⚠️ Alerta **agravado** desde o primeiro aviso' : '');
  }

  const linhas = ctos.slice(0, 15).map(c => {
    const mapa = (c.latitude && c.longitude) ? ` · [mapa](https://maps.google.com/?q=${c.latitude},${c.longitude})` : '';
    return `• **${c.descricao || 'CTO ' + c.cto}** — ${c.off}/${c.total} off · portas ${(c.portas || []).join(', ')}${mapa}`;
  });
  if (ctos.length > 15) linhas.push(`… e mais ${ctos.length - 15} CTOs`);

  const fields = [
    { name: 'OLT', value: a.olt || '—', inline: true },
    { name: 'PON', value: a.ponid || '—', inline: true },
    { name: 'Início', value: a.inicio || '—', inline: true },
    { name: `CTOs afetadas (${ctos.length})`, value: corta(linhas.join('\n') || '—', 1024) },
  ];
  if (Number(a.sinal_ruim) > 0) {
    fields.push({ name: 'Sinal antes da queda', value: `${a.sinal_ruim} ONU(s) já com sinal abaixo de −27 dBm (pode ser problema individual)` });
  }

  const body = {
    content: '',
    allowed_mentions: { parse: [] },
    embeds: [{
      title: corta(titulo, 256),
      description: desc,
      color: COR[a.evento] ?? COR.novo,
      fields,
      footer: { text: `Alerta #${a.id} · NOC` },
      timestamp: new Date().toISOString(),
    }],
  };
  const editar = !!a.discord_msg_id;
  return { json: {
    id: a.id, evento: a.evento, afetados: a.afetados,
    method: editar ? 'PATCH' : 'POST',
    url: editar ? `${API}/channels/${CANAL}/messages/${a.discord_msg_id}` : `${API}/channels/${CANAL}/messages`,
    body,
  } };
});

// Resultado do Discord: ok -> marca enviado; 404 na edicao -> mensagem apagada, recria no proximo ciclo; outro -> fica pendente
const reqs = $('Montar mensagem').all();
return $input.all().map((it, i) => {
  const r = reqs[i].json;
  const code = Number(it.json.statusCode || 0);
  let status = 'erro';
  if (code >= 200 && code < 300) status = 'ok';
  else if (code === 404 && r.method === 'PATCH') status = 'reset';
  const msg = (it.json.body && it.json.body.id) ? String(it.json.body.id) : '';
  return { json: { id: r.id, evento: r.evento, afetados: r.afetados, status, code, msg } };
});

const erros = $('Resultado').all().filter(i => i.json.status === 'erro');
if (erros.length) throw new Error('Discord recusou ' + erros.length + ' envio(s): ' + erros.map(e => `#${e.json.id} HTTP ${e.json.code}`).join(', '));
return [{ json: { ok: true } }];
